<?php
require __DIR__ . '/layout.php';
$pdo = db();
$id = filter_input(INPUT_GET, 'id', FILTER_VALIDATE_INT) ?: 0;
$prospect = null;
if ($id) { $stmt = $pdo->prepare('SELECT * FROM prospects WHERE id = ?'); $stmt->execute([$id]); $prospect = $stmt->fetch(); if (!$prospect) { http_response_code(404); exit('Prospect not found.'); } }

if ($_SERVER['REQUEST_METHOD'] === 'POST') {
    verify_csrf(); $action = (string) ($_POST['action'] ?? '');
    if ($action === 'save') {
        $data = prospect_payload();
        if ($data['prospect'] === '') { flash('A prospect name is required.', 'error'); redirect($id ? prospect_url($id) : 'prospect.php'); }
        if ($id) {
            $columns = array_keys($data); $set = implode(', ', array_map(fn($key) => "$key = ?", $columns));
            $pdo->prepare("UPDATE prospects SET $set WHERE id = ?")->execute([...array_values($data), $id]);
            add_activity($id, 'Note added', 'Prospect details updated.'); flash('Prospect updated.'); redirect(prospect_url($id));
        }
        $columns = array_keys($data); $placeholders = implode(', ', array_fill(0, count($columns), '?'));
        $pdo->prepare('INSERT INTO prospects (' . implode(', ', $columns) . ') VALUES (' . $placeholders . ')')->execute(array_values($data));
        $newId = (int) $pdo->lastInsertId(); add_activity($newId, 'Research added', 'Prospect created.'); flash('Prospect added.'); redirect(prospect_url($newId));
    }
    if (!$id) { http_response_code(400); exit('A prospect is required for this action.'); }
    if ($action === 'delete') { $pdo->prepare('DELETE FROM prospects WHERE id = ?')->execute([$id]); flash('Prospect deleted.'); redirect('prospects.php'); }
    if ($action === 'activity') { $type = valid_choice((string)($_POST['activity_type'] ?? ''), CRM_ACTIVITY_TYPES, 'Note added'); $note = mb_substr(trim((string)($_POST['note'] ?? '')), 0, 20000); add_activity($id, $type, $note, date_or_null((string)($_POST['activity_date'] ?? ''))); flash('Activity added.'); redirect(prospect_url($id)); }
    if ($action === 'draft') {
        $draftId = filter_var($_POST['draft_id'] ?? null, FILTER_VALIDATE_INT) ?: 0;
        $draft = [mb_substr(trim((string)($_POST['recipient'] ?? '')), 0, 190), mb_substr(trim((string)($_POST['subject'] ?? '')), 0, 255), mb_substr(trim((string)($_POST['channel'] ?? 'Email')), 0, 80), mb_substr(trim((string)($_POST['body'] ?? '')), 0, 30000), valid_choice((string)($_POST['draft_status'] ?? ''), CRM_DRAFT_STATUSES, 'Draft')];
        if ($draftId) { $pdo->prepare('UPDATE outreach_drafts SET recipient=?, subject=?, channel=?, body=?, status=? WHERE id=? AND prospect_id=?')->execute([...$draft, $draftId, $id]); }
        else { $pdo->prepare('INSERT INTO outreach_drafts (prospect_id, recipient, subject, channel, body, status) VALUES (?, ?, ?, ?, ?, ?)')->execute([$id, ...$draft]); }
        add_activity($id, $draft[4] === 'Sent Manually' ? 'Email sent manually' : 'Draft prepared', $draft[1] ?: 'Outreach draft updated.'); flash('Outreach draft saved.'); redirect(prospect_url($id));
    }
}

$prospect = $prospect ?: array_fill_keys(['prospect','category','opportunity_type','website','social_links','why_kikku_fits','partnership_idea','commercial_potential','strategic_value','score','contact_person','contact_role','email','social_contact','best_channel','status','last_contact','follow_up_date','reply_summary','recommended_next_step','notes'], '');
$prospect['opportunity_type'] = $prospect['opportunity_type'] ?: 'Strategic Collab'; $prospect['status'] = $prospect['status'] ?: 'Researching';
if ($id) { $activities = $pdo->prepare('SELECT * FROM activities WHERE prospect_id = ? ORDER BY activity_date DESC, id DESC'); $activities->execute([$id]); $activities = $activities->fetchAll(); $drafts = $pdo->prepare('SELECT * FROM outreach_drafts WHERE prospect_id = ? ORDER BY updated_at DESC'); $drafts->execute([$id]); $drafts = $drafts->fetchAll(); }
page_start($id ? $prospect['prospect'] : 'Add prospect', 'prospects'); ?>
<div class="page-head"><div><p><a href="prospects.php">← All prospects</a></p><h1><?= $id ? e($prospect['prospect']) : 'Add prospect' ?></h1><p><?= $id ? 'Keep the opportunity, next action and history in one practical record.' : 'Add a researched partnership opportunity to the pipeline.' ?></p></div><?php if ($id): ?><a class="button secondary" href="<?= e($prospect['website'] ?: '#') ?>" target="_blank" rel="noopener noreferrer" <?= $prospect['website'] ? '' : 'style="visibility:hidden"' ?>>Open website ↗</a><?php endif; ?></div>
<form method="post" class="panel"><input type="hidden" name="csrf" value="<?= e(csrf_token()) ?>"><input type="hidden" name="action" value="save"><div class="form-grid two-col">
<?php $fields = [['prospect','Prospect','text',true],['category','Category','text',false],['website','Website','url',false],['social_links','Website / social links','textarea',false],['why_kikku_fits','Why Kikku fits','textarea',false],['partnership_idea','Partnership idea','textarea',false],['commercial_potential','Commercial potential','textarea',false],['strategic_value','Strategic value','textarea',false],['contact_person','Contact person','text',false],['contact_role','Role','text',false],['email','Email','email',false],['social_contact','Social contact','text',false],['best_channel','Best channel','text',false],['reply_summary','Reply summary','textarea',false],['recommended_next_step','Recommended next step','textarea',false],['notes','Notes','textarea',false]]; ?>
<div class="field"><label>Opportunity type</label><select name="opportunity_type"><?php foreach(CRM_OPPORTUNITY_TYPES as $choice): ?><option <?= $prospect['opportunity_type']===$choice?'selected':'' ?>><?= e($choice) ?></option><?php endforeach; ?></select></div><div class="field"><label>Status</label><select name="status"><?php foreach(CRM_STATUSES as $choice): ?><option <?= $prospect['status']===$choice?'selected':'' ?>><?= e($choice) ?></option><?php endforeach; ?></select></div><div class="field"><label>Score /10</label><input name="score" type="number" min="0" max="10" value="<?= e((string)$prospect['score']) ?>"></div><div class="field"><label>Last contact</label><input name="last_contact" type="date" value="<?= e((string)$prospect['last_contact']) ?>"></div><div class="field"><label>Follow-up date</label><input name="follow_up_date" type="date" value="<?= e((string)$prospect['follow_up_date']) ?>"></div>
<?php foreach ($fields as [$key,$label,$type,$required]): ?><div class="field <?= $type==='textarea'?'full':'' ?>"><label><?= e($label) ?></label><?php if ($type==='textarea'): ?><textarea name="<?= e($key) ?>"><?= e($prospect[$key]) ?></textarea><?php else: ?><input name="<?= e($key) ?>" type="<?= e($type) ?>" value="<?= e($prospect[$key]) ?>" <?= $required?'required':'' ?>><?php endif; ?></div><?php endforeach; ?></div><div class="actions"><button class="button" type="submit">Save prospect</button><a class="button secondary" href="prospects.php">Cancel</a></div></form>
<?php if ($id): ?><div class="two"><section class="panel"><h2>Activity timeline</h2><form method="post" class="stack"><input type="hidden" name="csrf" value="<?= e(csrf_token()) ?>"><input type="hidden" name="action" value="activity"><div class="form-grid"><div class="field"><label>Activity</label><select name="activity_type"><?php foreach(CRM_ACTIVITY_TYPES as $type): ?><option><?= e($type) ?></option><?php endforeach; ?></select></div><div class="field"><label>Date</label><input type="date" name="activity_date" value="<?= date('Y-m-d') ?>"></div><div class="field full"><label>Note</label><textarea name="note" placeholder="What happened, what was agreed, or what to do next?"></textarea></div></div><button class="button small" type="submit">Add to timeline</button></form><div class="timeline"><?php foreach($activities as $activity): ?><div class="timeline-item"><strong><?= e($activity['activity_type']) ?></strong><span class="muted"><?= e($activity['activity_date']) ?></span><?php if ($activity['note']): ?><div><?= nl2br(e($activity['note'])) ?></div><?php endif; ?></div><?php endforeach; ?><?php if (!$activities): ?><p class="empty">No activity yet.</p><?php endif; ?></div></section><section class="panel"><h2>Outreach drafts</h2><?php foreach($drafts as $draft): ?><details class="row"><summary><strong><?= e($draft['subject'] ?: 'Untitled draft') ?></strong> · <?= e($draft['channel']) ?> · <?= status_badge($draft['status']) ?></summary><p class="muted">To: <?= e($draft['recipient'] ?: '—') ?></p><div><?= nl2br(e($draft['body'])) ?></div></details><?php endforeach; ?><form method="post" class="stack" style="margin-top:18px"><input type="hidden" name="csrf" value="<?= e(csrf_token()) ?>"><input type="hidden" name="action" value="draft"><div class="form-grid"><div class="field"><label>Recipient</label><input name="recipient" value="<?= e($prospect['email'] ?: $prospect['contact_person']) ?>"></div><div class="field"><label>Channel</label><select name="channel"><option>Email</option><option>Instagram DM</option><option>Facebook DM</option><option>LinkedIn</option><option>Other</option></select></div><div class="field full"><label>Subject</label><input name="subject"></div><div class="field full"><label>Draft</label><textarea name="body"></textarea></div><div class="field"><label>State</label><select name="draft_status"><?php foreach(CRM_DRAFT_STATUSES as $state): ?><option><?= e($state) ?></option><?php endforeach; ?></select></div></div><button class="button small" type="submit">Save draft</button></form></section></div><section class="panel danger-zone"><h3>Delete prospect</h3><p class="muted">This permanently removes the prospect, its activities and outreach drafts.</p><form method="post" onsubmit="return confirm('Delete this prospect and its activity history permanently?');"><input type="hidden" name="csrf" value="<?= e(csrf_token()) ?>"><input type="hidden" name="action" value="delete"><button class="button danger small" type="submit">Delete prospect</button></form></section><?php endif; ?>
<?php page_end();
